  // ===== VOICEOVER TEXT OVERLAY =====
  var voText1Op = f >= 10 ? (f < 40 ? eo3(p(10, 40)) : (f < 120 ? 1 : (f < 150 ? 1 - eo3(p(120, 150)) : 0))) : 0;
  if (voText1Op > 0) {
